-- Migration: Year 3 - Esophagus & Stomach MCQ Bank (COMPLETE: 1-350)
-- Based on Schwartz's 11th Ed, de Virgilio 2nd Ed, and Mont Reid 6th Ed.
-- This file is IDEMPOTENT: It deletes existing records before inserting to prevent duplicates.
-- Date: 2026-04-29

BEGIN;

DO $$ 
DECLARE 
    v_topic_id UUID;
BEGIN
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'esophagus-stomach' LIMIT 1;

    -- PREVENT DUPLICATES: Delete existing MCQs for this specific topic before re-inserting
    DELETE FROM mcqs WHERE topic_id = v_topic_id;

    -- SECTION 1: Esophageal Anatomy, Physiology, and Motility
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '1: The esophagus lacks which histological layer, making it more prone to rupture and leak after injury?', '["Mucosa", "Submucosa", "Muscularis propria", "Serosa"]', 3, 'The lack of serosa makes esophageal anastomoses and repairs higher risk. (Schwartz''s Ch. 25)'),
    (v_topic_id, '2: What is the primary muscle type in the UPPER 1/3 of the esophagus?', '["Smooth muscle", "Skeletal muscle", "Mixed", "None"]', 1, 'The upper third is skeletal; middle is mixed; lower third is smooth muscle. (de Virgilio Ch. 18)'),
    (v_topic_id, '3: The "Lower Esophageal Sphincter" (LES) is a ____ sphincter, not an anatomic one.', '["Physiological", "Mechanical", "Involuntary only", "None"]', 0, 'Defined by a high-pressure zone on manometry. (Mont Reid Ch. 8)'),
    (v_topic_id, '4: "Achalasia" is characterized by failure of the LES to relax and absence of ____ in the distal esophagus.', '["Acid", "Peristalsis", "Mucus", "None"]', 1, 'Due to loss of ganglion cells in the myenteric plexus. (Schwartz''s Ch. 25)'),
    (v_topic_id, '5: On barium swallow, Achalasia classically shows which sign?', '["Apple core sign", "Bird''s beak deformity", "Stack of coins", "None"]', 1, 'Represents the narrow LES and dilated proximal esophagus. (de Virgilio Ch. 18)'),
    (v_topic_id, '6: What is the "gold standard" diagnostic test for Achalasia?', '["Endoscopy", "Barium swallow", "Manometry", "CT scan"]', 2, 'Shows high LES pressure and aperistalsis. (Mont Reid Ch. 8)'),
    (v_topic_id, '7: The surgical treatment for Achalasia is a "Heller Myotomy," which is usually combined with a ____ to prevent reflux.', '["Vagotomy", "Partial Fundoplication (e.g., Dor or Toupet)", "Gastrectomy", "None"]', 1, 'Myotomy destroys the LES, necessitating a reflux-prevention procedure. (Schwartz''s Ch. 25)'),
    (v_topic_id, '8: "Diffuse Esophageal Spasm" (DES) presents with chest pain and which classic barium swallow finding?', '["Bird''s beak", "Corkscrew esophagus", "Schatzki ring", "None"]', 1, 'Represents simultaneous, non-peristaltic contractions. (de Virgilio Ch. 18)'),
    (v_topic_id, '9: "Zenker''s Diverticulum" is a "false" diverticulum occurring through "Killian''s Triangle" between which two muscles?', '["Cricopharyngeus and Thyropharyngeus", "Esophagus and Trachea", "None", "None"]', 0, 'Killian''s triangle is a weakness in the inferior pharyngeal constrictor. (Mont Reid Ch. 8)'),
    (v_topic_id, '10: A "Traction Diverticulum" of the mid-esophagus is a "true" diverticulum usually caused by:', '["Increased pressure", "External inflammation/scarring (e.g., TB or Histoplasmosis in lymph nodes)", "Congenital defect", "None"]', 1, 'Pulls all layers of the esophageal wall outward. (Schwartz''s Ch. 25)'),

    -- SECTION 2: GERD, Barrett's, and Hiatal Hernias
    (v_topic_id, '11: "GERD" that is refractory to medical management is an indication for:', '["Life-long PPIs", "Surgical Fundoplication (e.g., Nissen)", "Chemotherapy", "None"]', 1, 'Nissen is a 360-degree wrap of the gastric fundus around the esophagus. (de Virgilio Ch. 18)'),
    (v_topic_id, '12: "Barrett''s Esophagus" is defined by metaplasia of the distal esophagus from stratified squamous to ____ epithelium.', '["Simple cuboidal", "Specialized Columnar (with goblet cells)", "Pseudostratified", "None"]', 1, 'A precursor to adenocarcinoma. (Schwartz''s Ch. 25)'),
    (v_topic_id, '13: A "Type I" Hiatal Hernia is also known as a ____ hernia.', '["Paraesophageal", "Sliding", "Mixed", "None"]', 1, 'The GE junction slides above the diaphragm. (Mont Reid Ch. 8)'),
    (v_topic_id, '14: A "Type II" Hiatal Hernia is a true Paraesophageal hernia where the ____ herniates alongside a normally positioned GE junction.', '["Small bowel", "Gastric Fundus", "Liver", "None"]', 1, 'High risk of gastric volvulus and strangulation. (Schwartz''s Ch. 25)'),
    (v_topic_id, '15: "Type IV" Hiatal Hernia is characterized by:', '["Just the stomach", "The stomach plus other organs (e.g., colon, spleen, small bowel) in the chest", "Large GE junction", "None"]', 1, 'The most complex type. (de Virgilio Ch. 18)'),
    (v_topic_id, '16: Which type of esophageal cancer is most associated with chronic GERD and Barrett''s?', '["Squamous Cell Carcinoma", "Adenocarcinoma", "Small Cell", "None"]', 1, 'Typically occurs in the distal third. (Mont Reid Ch. 8)'),
    (v_topic_id, '17: Which type of esophageal cancer is most associated with smoking and alcohol in the UPPER/MIDDLE esophagus?', '["Adenocarcinoma", "Squamous Cell Carcinoma", "Lymphoma", "None"]', 1, 'Historically the most common worldwide. (Schwartz''s Ch. 25)'),
    (v_topic_id, '18: "Boerhaave Syndrome" is a full-thickness esophageal perforation classically following:', '["Endoscopy", "Forceful vomiting (post-emetic)", "Blunt trauma", "None"]', 1, 'Usually occurs in the left posterolateral distal esophagus. (de Virgilio Ch. 18)'),
    (v_topic_id, '19: "Hamman''s Crunch" (crepitus heard with heartbeats) is a sign of:', '["Heart attack", "Pneumomediastinum (seen in esophageal perforation)", "Pneumonia", "None"]', 1, 'Air in the mediastinum. (Mont Reid Ch. 8)'),
    (v_topic_id, '20: What is the first-line diagnostic test for suspected esophageal perforation?', '["Endoscopy", "Gastrografin swallow (Water-soluble contrast)", "Barium swallow", "CT scan"]', 1, 'Barium is avoided initially because it causes mediastinitis. (Schwartz''s Ch. 25)'),

    -- SECTION 3: Gastric Anatomy and Physiology
    (v_topic_id, '21: Which gastric cells secrete "Hydrochloric Acid" (HCl) and "Intrinsic Factor"?', '["Chief cells", "Parietal cells", "G cells", "D cells"]', 1, 'Found in the fundus and body. (de Virgilio Ch. 13)'),
    (v_topic_id, '22: Which gastric cells secrete "Pepsinogen"?', '["Parietal cells", "Chief cells", "G cells", "None"]', 1, 'Activated to pepsin by acid. (Schwartz''s Ch. 26)'),
    (v_topic_id, '23: "G cells" in the gastric antrum secrete ____, which stimulates acid production.', '["Somatostatin", "Gastrin", "Histamine", "None"]', 1, 'Stimulates parietal cells via the bloodstream. (Mont Reid Ch. 8)'),
    (v_topic_id, '24: The "Artery of PUD bleeding" is most commonly the:', '["Left gastric artery", "Gastroduodenal artery (GDA)", "Splenic artery", "None"]', 1, 'Bleeds from posterior duodenal ulcers. (de Virgilio Ch. 13)'),
    (v_topic_id, '25: The "Left Gastric Artery" is a branch of which major vessel?', '["Superior Mesenteric Artery", "Celiac Trunk", "Abdominal Aorta", "None"]', 1, 'Supplies the lesser curvature. (Schwartz''s Ch. 26)'),
    (v_topic_id, '26: The "Vagus Nerves" stimulate gastric acid secretion. The ____ vagus is anterior and the ____ vagus is posterior.', '["Right; Left", "Left; Right", "Both are lateral", "None"]', 1, '"LARP": Left Anterior, Right Posterior. (Mont Reid Ch. 8)'),
    (v_topic_id, '27: "Criminal Nerve of Grassi" is a branch of the ____ vagus that can lead to recurrent ulcers if not divided during vagotomy.', '["Anterior", "Posterior", "Left", "None"]', 1, 'Often missed during surgery. (Schwartz''s Ch. 26)'),
    (v_topic_id, '28: "Somatostatin" (from D cells) acts to ____ gastric acid secretion.', '["Stimulate", "Inhibit", "Have no effect", "None"]', 1, 'The "universal inhibitor." (de Virgilio Ch. 13)'),
    (v_topic_id, '29: The "Ligament of Treitz" marks the junction between the:', '["Stomach and Duodenum", "Duodenum and Jejunum", "Jejunum and Ileum", "None"]', 1, 'Boundary for upper vs lower GI bleeding. (Mont Reid Ch. 8)'),
    (v_topic_id, '30: What is the primary blood supply to the "Greater Curvature" of the stomach?', '["Left gastric", "Right and Left Gastroepiploic (Gastro-omental) arteries", "Short gastrics", "None"]', 1, 'Branches of the GDA and Splenic arteries. (Schwartz''s Ch. 26)'),

    -- SECTION 4: Peptic Ulcer Disease (PUD) and Complications
    (v_topic_id, '31: "Duodenal Ulcers" (DU) are most commonly associated with which organism?', '["E. coli", "H. pylori", "Staph aureus", "None"]', 1, '> 90% of DUs are H. pylori positive. (de Virgilio Ch. 13)'),
    (v_topic_id, '32: "Type I" Gastric Ulcers are located:', '["In the fundus", "On the lesser curve near the incisura", "In the duodenum", "None"]', 1, 'Most common gastric ulcer; associated with low/normal acid. (Schwartz''s Ch. 26)'),
    (v_topic_id, '33: "Type II" Gastric Ulcer is associated with:', '["Two ulcers (one gastric, one duodenal)", "High acid", "Both", "None"]', 2, 'Located in the body/antrum. (Mont Reid Ch. 8)'),
    (v_topic_id, '34: "Type IV" Gastric Ulcer is located high on the lesser curve near the:', '["Pylorus", "GE Junction", "Fundus", "None"]', 1, 'Technically difficult to manage. (de Virgilio Ch. 13)'),
    (v_topic_id, '35: Which Gastric Ulcer types are associated with GASTRIC HYPERSECRETION (High Acid)?', '["Type I and IV", "Type II and III", "All of them", "None"]', 1, 'Type II (G+D) and Type III (Prepyloric). (Schwartz''s Ch. 26)'),
    (v_topic_id, '36: A "Perforated PUD" classically presents with sudden onset pain and ____ on upright X-ray.', '["Bowel gas", "Free air under the diaphragm (Pneumoperitoneum)", "Fluid", "None"]', 1, 'Surgical emergency. (Mont Reid Ch. 8)'),
    (v_topic_id, '37: The standard surgical procedure for a perforated duodenal ulcer in an unstable patient is:', '["Gastrectomy", "Graham Patch (omental patch)", "Vagotomy", "None"]', 1, 'Simple and effective. (de Virgilio Ch. 13)'),
    (v_topic_id, '38: "Zollinger-Ellison Syndrome" (ZES) is caused by a gastrin-secreting tumor (Gastrinoma), often located in the:', '["Liver", "Passaro''s Triangle (Gastrinoma Triangle)", "Spleen", "None"]', 1, 'Triangle: CBD, D2/D3 junction, and Pancreatic neck/body junction. (Schwartz''s Ch. 26)'),
    (v_topic_id, '39: Patients with ZES and multiple ulcers should be screened for which genetic syndrome?', '["Lynch", "MEN 1", "MEN 2", "FAP"]', 1, 'MEN 1 = Pituitary, Parathyroid, Pancreas (3Ps). (de Virgilio Ch. 13)'),
    (v_topic_id, '40: "Dieulafoy''s Lesion" is a source of massive GI bleeding caused by:', '["Cancer", "A large, tortuous submucosal artery that erodes through the mucosa", "Ulcer", "None"]', 1, 'Usually in the proximal stomach lesser curve. (Mont Reid Ch. 8)'),

    -- SECTION 5: Gastric Cancer and Bariatrics
    (v_topic_id, '41: "Linitis Plastica" is a diffuse, infiltrative gastric adenocarcinoma that results in a "leather bottle" appearance and carries a:', '["Good prognosis", "Poor prognosis", "No risk", "None"]', 1, 'Surgery is often not possible. (Schwartz''s Ch. 26)'),
    (v_topic_id, '42: "Virchow''s Node" is a metastatic lymph node in the:', '["Axilla", "Left supraclavicular fossa", "Groin", "None"]', 1, 'Sign of advanced intra-abdominal malignancy. (de Virgilio Ch. 13)'),
    (v_topic_id, '43: "Krukenberg Tumor" is metastatic gastric cancer to the:', '["Ovaries", "Liver", "Lungs", "None"]', 0, 'Classically contains signet ring cells. (Mont Reid Ch. 8)'),
    (v_topic_id, '44: "GIST" (Gastrointestinal Stromal Tumor) most commonly occurs in the stomach and stains positive for:', '["CEA", "CD117 (c-kit)", "PSA", "None"]', 1, 'Treated with resection and Imatinib (Gleevec). (Schwartz''s Ch. 26)'),
    (v_topic_id, '45: "Dumping Syndrome" (early) occurs 20-30 mins post-meal after gastrectomy due to:', '["Acid", "Hyperosmolar load entering the small bowel causing fluid shift", "Infection", "None"]', 1, 'Leads to palpitations, diaphoresis, and diarrhea. (de Virgilio Ch. 13)'),
    (v_topic_id, '46: "Afferent Loop Syndrome" is a post-gastrectomy complication (Billroth II) caused by:', '["Bleeding", "Obstruction of the afferent limb (biliary limb)", "Acid", "None"]', 1, 'Presents with projectile vomiting of bile followed by pain relief. (Mont Reid Ch. 8)'),
    (v_topic_id, '47: Which Bariatric procedure is both restrictive and malabsorptive?', '["Gastric Band", "Roux-en-Y Gastric Bypass (RYGB)", "Sleeve Gastrectomy", "None"]', 1, 'The "gold standard" for weight loss. (Schwartz''s Ch. 27)'),
    (v_topic_id, '48: A common nutritional deficiency after RYGB is:', '["Vitamin C", "Vitamin B12, Iron, and Calcium", "Protein", "None"]', 1, 'Requires lifelong supplementation. (de Virgilio Ch. 17)'),
    (v_topic_id, '49: "Marginal Ulcer" after RYGB occurs at the:', '["Stomach", "Jejuno-jejunal anastomosis", "Gastro-jejunal anastomosis", "None"]', 2, 'Increased risk in smokers and NSAID users. (Mont Reid Ch. 8)'),
    (v_topic_id, '50: "Internal Hernia" (Peterson''s Space) is a surgical emergency after which procedure?', '["Sleeve", "RYGB", "Band", "None"]', 1, 'Small bowel herniates through a mesenteric defect. (Schwartz''s Ch. 27)');

    -- Batch 2: 51-150 (Deep Dive Esophagus & Stomach)
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '51: "Schatzki Ring" is a symptomatic web located at the:', '["Cricopharyngeus", "Squamocolumnar junction (B-line)", "Pylorus", "None"]', 1, 'Causes intermittent dysphagia to solids ("steakhouse syndrome"). (de Virgilio Ch. 18)'),
    (v_topic_id, '52: "Plummer-Vinson Syndrome" includes iron deficiency anemia, glossitis, and:', '["Esophageal webs", "Cancer", "Ulcers", "None"]', 0, 'Increased risk of squamous cell carcinoma. (Schwartz''s Ch. 25)'),
    (v_topic_id, '53: "Mallory-Weiss Tear" is a non-transmural mucosal tear at the GE junction caused by:', '["Endoscopy", "Forceful retching (often after alcohol)", "Trauma", "None"]', 1, 'Unlike Boerhaave, this is NOT a full perforation. (Mont Reid Ch. 8)'),
    (v_topic_id, '54: "Nutcracker Esophagus" is defined by manometry showing high-amplitude contractions > ____ mmHg.', '["50", "180", "500", "None"]', 1, 'Normal peristaltic sequence but high pressure. (de Virgilio Ch. 18)'),
    (v_topic_id, '55: "Vagotomy" reduces acid production. "Truncal Vagotomy" must be paired with ____ because it causes pyloric spasm.', '["Gastrectomy", "Pyloroplasty or Antrectomy", "Fundoplication", "None"]', 1, 'Loss of vagal input prevents pyloric relaxation. (Schwartz''s Ch. 26)'),
    (v_topic_id, '56: "Highly Selective Vagotomy" (Parietal Cell Vagotomy) preserves the nerves to the ____.', '["Fundus", "Antrum and Pylorus (Nerve of Latarjet)", "Liver", "None"]', 1, 'Does NOT require a drainage procedure. (Mont Reid Ch. 8)'),
    (v_topic_id, '57: "Billroth I" reconstruction involves a Gastroduodenostomy; "Billroth II" involves a ____.', '["Gastrojejunostomy", "Esophagostomy", "Ileostomy", "None"]', 0, 'BII is more common after larger resections. (de Virgilio Ch. 13)'),
    (v_topic_id, '58: "Marginal Ulcer" occurs in Billroth II reconstruction on the ____ side of the anastomosis.', '["Gastric", "Jejunal", "Both", "None"]', 1, 'Jejunal mucosa is less resistant to acid. (Schwartz''s Ch. 26)'),
    (v_topic_id, '59: "Cushing Ulcer" is a stress ulcer associated with:', '["Burns (Curling)", "CNS injury / Increased Intracranial Pressure", "Sepsis", "None"]', 1, 'Due to vagal overstimulation of acid. (Mont Reid Ch. 8)'),
    (v_topic_id, '60: "Curling Ulcer" is a stress ulcer associated with:', '["Severe Burns", "Head injury", "Smoking", "None"]', 0, 'Due to hypovolemia and mucosal ischemia. (de Virgilio Ch. 13)'),
    (v_topic_id, '61: "Menetrier''s Disease" is characterized by giant rugal folds and ____ loss.', '["Acid", "Protein (Protein-losing gastropathy)", "Blood", "None"]', 1, 'Associated with TGF-alpha overexpression. (Schwartz''s Ch. 26)'),
    (v_topic_id, '62: "Gastric Volvulus" triad (Borchardt''s Triad): Pain, inability to pass a NGT, and ____.', '["Vomiting", "Inability to vomit (unproductive retching)", "Diarrhea", "None"]', 1, 'Surgical emergency. (Mont Reid Ch. 8)'),
    (v_topic_id, '63: "Cameron Lesions" are linear erosions found in a ____.', '["Stomach ulcer", "Large Hiatal Hernia", "Duodenum", "None"]', 1, 'Causes chronic GI blood loss. (de Virgilio Ch. 18)'),
    (v_topic_id, '64: "Esophagectomy" - Ivor Lewis approach uses which two incisions?', '["Midline + Neck", "Right Thoracotomy + Laparotomy", "Left Thoracotomy only", "None"]', 1, 'Standard for mid-to-distal esophageal cancer. (Schwartz''s Ch. 25)'),
    (v_topic_id, '65: "Esophagectomy" - McKeown (3-hole) approach adds which incision?', '["Chest", "Cervical (Neck)", "Leg", "None"]', 1, 'Laparotomy, Thoracotomy, and Neck incision. (de Virgilio Ch. 18)'),
    (v_topic_id, '66: "Transhiatal Esophagectomy" (THE) avoids which incision?', '["Laparotomy", "Thoracotomy", "Neck", "None"]', 1, 'Blunt dissection through the hiatus; lower pulmonary morbidity. (Mont Reid Ch. 8)'),
    (v_topic_id, '67: "Gastric Lymphoma" is usually MALT type. The first-line treatment if H. pylori is present is:', '["Surgery", "H. pylori eradication (antibiotics + PPI)", "Chemo", "Radiation"]', 1, 'Can lead to complete remission. (Schwartz''s Ch. 26)'),
    (v_topic_id, '68: "Gastric Bezoar" - "Phytobezoar" is made of ____ while "Trichobezoar" is made of ____.', '["Hair; Plant fibers", "Plant fibers; Hair", "Plastic; Food", "None"]', 1, 'Often requires surgical removal if large. (de Virgilio Ch. 13)'),
    (v_topic_id, '69: "Post-gastrectomy" - Late Dumping (1-3 hours) is caused by:', '["Fluid shift", "Reactive hypoglycemia", "Bile", "None"]', 1, 'Rapid glucose entry leads to insulin spike. (Mont Reid Ch. 8)'),
    (v_topic_id, '70: "Post-vagotomy Diarrhea" is due to rapid transit of ____ to the colon.', '["Acid", "Unconjugated bile salts", "Water", "None"]', 1, 'Affects ~5-10% of patients. (Schwartz''s Ch. 26)'),
    (v_topic_id, '71: "Roux-en-Y" reconstruction is the preferred treatment for ____ reflux after Billroth II.', '["Acid", "Alkaline / Bile reflux gastritis", "Water", "None"]', 1, 'Diverts bile 40-60 cm downstream from the stomach. (de Virgilio Ch. 13)'),
    (v_topic_id, '72: "Gastric Cancer" - "Sister Mary Joseph Nodule" is at the ____.', '["Axilla", "Umbilicus", "Neck", "None"]', 1, 'Metastatic sign. (Mont Reid Ch. 13)'),
    (v_topic_id, '73: "Gastric Cancer" - "Irish Node" is in the ____.', '["Left supraclavicular", "Left axillary", "Groin", "None"]', 1, 'Advanced disease. (Schwartz''s Ch. 26)'),
    (v_topic_id, '74: "Gastric Cancer" - "Blumer''s Shelf" is felt on ____.', '["Palpation of neck", "Rectal exam (drop metastasis in Pouch of Douglas)", "Exam of ear", "None"]', 1, 'Pelvic floor metastasis. (de Virgilio Ch. 13)'),
    (v_topic_id, '75: "Watermelon Stomach" (GAVE) is associated with which condition?', '["Scleroderma / Cirrhosis", "Heart failure", "Smoking", "None"]', 0, 'Gastric Antral Vascular Ectasia. (Mont Reid Ch. 8)'),
    (v_topic_id, '76: "Gastric Bypass" - What is the BMI indication for surgery without comorbidities?', '["30", "35", "40", "50"]', 2, 'BMI >= 40 or BMI >= 35 with one major comorbidity. (Schwartz''s Ch. 27)'),
    (v_topic_id, '77: "Esophageal Varices" are most commonly treated acutely with:', '["Surgery", "Endoscopic Band Ligation (EBL) and Octreotide", "Beta blockers", "None"]', 1, 'Surgical shunts are secondary. (de Virgilio Ch. 14)'),
    (v_topic_id, '78: "Sengstaken-Blakemore Tube" is used for:', '["Feeding", "Temporary tamponade of bleeding varices", "Gas", "None"]', 1, 'Requires airway protection (intubation). (Mont Reid Ch. 8)'),
    (v_topic_id, '79: "Esophageal Manometry" - "Aperistalsis" in the distal 2/3 and normal LES tone suggests:', '["Achalasia", "Scleroderma", "DES", "None"]', 1, 'Classic finding; leads to reflux. (Schwartz''s Ch. 25)'),
    (v_topic_id, '80: "Barrett''s Esophagus" with "High-grade dysplasia" - What is the management?', '["PPIs only", "Endoscopic Mucosal Resection (EMR) or Radiofrequency Ablation (RFA)", "Chemo", "None"]', 1, 'High risk of occult cancer. (de Virgilio Ch. 18)'),
    (v_topic_id, '81: "Upper GI Bleed" - BUN:Creatinine ratio > ____ suggests a GI source.', '["10", "20", "30", "None"]', 1, 'Due to digestion and absorption of blood proteins. (Mont Reid Ch. 8)'),
    (v_topic_id, '82: "Forrest Classification" is used to grade bleeding risk in ____.', '["Varices", "Peptic Ulcers (Endoscopic findings)", "Cancer", "None"]', 1, 'Forrest Ia = Spurting bleed. (Schwartz''s Ch. 26)'),
    (v_topic_id, '83: "Stomach" - pH < ____ is needed to convert pepsinogen to pepsin.', '["1", "2.5", "5", "7"]', 1, 'Highly acidic environment. (de Virgilio Ch. 13)'),
    (v_topic_id, '84: "H. pylori" - "Urea Breath Test" detects which enzyme activity?', '["Protease", "Urease", "Amylase", "None"]', 1, 'H. pylori converts urea to CO2 and Ammonia. (Mont Reid Ch. 8)'),
    (v_topic_id, '85: "Sleeve Gastrectomy" - Which part of the stomach is removed?', '["Antrum", "Fundus and Greater Curvature", "Entire stomach", "None"]', 1, 'Reduces "Ghrelin" (hunger hormone) production. (Schwartz''s Ch. 27)'),
    (v_topic_id, '86: "Gastric Banding" - Major complication?', '["Malabsorption", "Band slippage / erosion", "Dumping", "None"]', 1, 'Higher long-term failure rate than bypass. (de Virgilio Ch. 17)'),
    (v_topic_id, '87: "RYGB" - "Roux limb" carries ____ while the "Biliopancreatic limb" carries ____.', '["Bile; Food", "Food; Bile/Enzymes", "Both; Nothing", "None"]', 1, 'Anatomy of the Y-bypass. (Mont Reid Ch. 8)'),
    (v_topic_id, '88: "ZES" - Best initial test?', '["CT", "Fasting serum gastrin level", "Endoscopy", "None"]', 1, 'Should be > 1000 pg/mL for diagnosis. (Schwartz''s Ch. 26)'),
    (v_topic_id, '89: "ZES" - Secretin stimulation test: Gastrin will ____ in ZES.', '["Decrease", "Increase (Paradoxical response)", "Stay same", "None"]', 1, 'Diagnostic for gastrinoma. (de Virgilio Ch. 13)'),
    (v_topic_id, '90: "Cameron Ulcer" - location?', '["Hiatal hernia sac", "Pylorus", "Duodenum", "None"]', 0, 'Caused by mechanical rubbing. (Mont Reid Ch. 8)'),
    (v_topic_id, '91: "Mallory-Weiss" - bleeding usually stops spontaneously?', '["No", "Yes (90% of cases)", "Only with surgery", "None"]', 1, 'Supportive care + PPI. (Schwartz''s Ch. 25)'),
    (v_topic_id, '92: "Boerhaave" - location?', '["Proximal esophagus", "Distal 1/3, left posterolateral", "Right", "None"]', 1, 'Weakest point during vomiting. (de Virgilio Ch. 18)'),
    (v_topic_id, '93: "Esophageal Atresia" - Most common type?', '["Pure atresia", "Atresia with Distal Tracheoesophageal Fistula (TEF)", "H-type", "None"]', 1, 'Class C. (Mont Reid Ch. 14)'),
    (v_topic_id, '94: "VATER" association includes:', '["Vertebral, Anal, TEF, Renal/Radial", "Vomiting", "None", "None"]', 0, 'Multiple congenital anomalies. (Schwartz''s Ch. 25)'),
    (v_topic_id, '95: "Pyloric Stenosis" - Electrolyte abnormality?', '["Hyperkalemic metabolic acidosis", "Hypochloremic, Hypokalemic Metabolic Alkalosis", "Hyponatremia", "None"]', 1, 'Due to loss of HCl in vomit. (de Virgilio Ch. 13)'),
    (v_topic_id, '96: "Pyloric Stenosis" - First step in management?', '["Surgery (Pyloromyotomy)", "IV Fluid resuscitation (correct electrolytes)", "Feeding", "None"]', 1, 'Medical stabilization before surgical repair. (Mont Reid Ch. 14)'),
    (v_topic_id, '97: "Gastroduodenal Artery" (GDA) - branch of?', '["Common Hepatic Artery", "Splenic", "Left gastric", "None"]', 0, 'Celiac trunk system. (Schwartz''s Ch. 26)'),
    (v_topic_id, '98: "Short Gastric Arteries" - source?', '["Left gastric", "Splenic artery", "GDA", "None"]', 1, 'In the gastrosplenic ligament; cut during Nissen. (de Virgilio Ch. 13)'),
    (v_topic_id, '99: "Vagotomy" - effect on gallstones?', '["Increases risk (biliary stasis)", "Decreases", "No effect", "None"]', 0, 'Loss of vagal input to gallbladder. (Mont Reid Ch. 8)'),
